insert into public.issues (project_id, title, severity, status, evidence, fix, now_note, owner, raised_on, resolved_on, sort) values
((select id from public.projects where slug = 'tailbone-treatment'), 'Prepaid balance is ₹1.10, so ads stop the moment it reaches zero', 'critical', 'in_progress', 'Available funds are ₹1.10 after 7 top-ups in 15 days. On 30 Sep the ₹1,316.55 month-end GST charge took the balance to ₹0.00, and 1 Oct shows no spend at all (2 Oct: ₹0.69, until a ₹600 top-up). The account is eligible for postpay.', 'Switch to postpay (billed on the 1st or at your threshold), or hold about ₹1,500 on top of campaign spend for the month-end GST. Keep Visa •••• 3337 as the backup card.', 'Decision: stay on prepay on purpose, because the balance is the only hard stop for the ₹10,000 cap. Doctor loads ₹3,500 on 19 Oct. The month-end GST is taken from the balance, so the load must cover it (Oct buffer is about ₹430).', 'me', '2026-10-18', null, 0),
((select id from public.projects where slug = 'tailbone-treatment'), 'Conversions carry no money value, so ROI cannot be measured', 'critical', 'open', 'Conv. value equals the conversion count in both campaigns (358.00 = 358, 9.00 = 9). Every conversion is worth a default ₹1.', 'Make only real actions Primary (call over 60 s, appointment form, WhatsApp click on the booking page). Move page views and generic clicks to Secondary. Assign a rupee value to each.', 'New campaign bids on clicks, so values do not matter yet. Before switching to conversion bidding (2 Nov at the earliest), set the call value from revenue per patient.', 'me', '2026-10-18', null, 1),
((select id from public.projects where slug = 'tailbone-treatment'), '24 of 27 conversion actions are Primary, and the recording ones are soft', 'critical', 'in_progress', 'All 27 actions add up to 47,997.84 conversions since 2014. Six actions are Active, all Primary: Local actions - Other engagements, Local actions - Directions, YouTube channel subscriptions, YouTube follow-on views, Clicks to call and Website visits (6,011 conversions). Real call wins from ads total 81, which is 0.2%.', 'Build the new campaign on the Phone call leads goal only, and keep every soft goal out of it. See the Conversion audit tab.', 'The new campaign uses only the Phone call leads goal, so soft actions cannot train it. Account-level clean-up (SPH and Call ads 2025 to Secondary) is still to do.', 'me', '2026-10-18', null, 2),
((select id from public.projects where slug = 'tailbone-treatment'), 'The 358 conversions probably came from soft actions', 'critical', 'open', 'Only soft, Google-hosted or YouTube-hosted actions are recording. A campaign buying YouTube and Maps inventory at ₹0.71 a click would collect exactly these. Not proven: the per-campaign split is unknown, and the table covers all time since 2014.', 'In Campaigns, segment by Conversion action for 17 Sep to 16 Oct. That shows which action produced the 358, and the clinic’s call and form log gives the real count.', 'Cannot be settled without the clinic’s call and WhatsApp log for 17 Sep – 16 Oct. Needed from the doctor.', 'client', '2026-10-18', null, 3),
((select id from public.projects where slug = 'tailbone-treatment'), '85% of recorded conversions come from two Analytics actions', 'high', 'open', 'The Universal Analytics action (22,945.50, Secondary) and the GA4 import tailbonetreatment_leads (17,659.34, Primary, counts Every, value ₹0) add to 40,604.84 of 47,997.84. They are lifetime totals since 2014, and neither is Active, so they are history.', 'Do not use them. Check in GA4 (Admin, Events) what tailbonetreatment_leads fires on before it is ever Primary again.', 'Left alone (no campaign uses them). Check the GA4 event before it is ever Primary again.', 'me', '2026-10-18', null, 4),
((select id from public.projects where slug = 'tailbone-treatment'), 'Some conversion actions cannot be edited', 'low', 'resolved', 'Calls from Smart Campaign Ads was created by Google Ads and can’t be edited. It only fires for Smart campaigns, and none is running.', 'Leave it. Control what counts through the campaign’s goal choice, not by editing every action.', 'No action needed. Controlled by the campaign’s goal choice.', 'me', '2026-10-18', '2026-10-18', 5),
((select id from public.projects where slug = 'tailbone-treatment'), 'Geography does not match the clinics', 'high', 'resolved', 'Ad text says clinics in New Delhi and Bangalore. PMax-5 targets Hyderabad, Gurugram, Mumbai, Pune, Noida, Delhi, Madhya Pradesh, Rajasthan, Chhattisgarh. PMax-4 targets Patna, Mumbai, Pune, Andhra Pradesh, Delhi, Gujarat, Maharashtra, Chhattisgarh. Karnataka was removed from PMax-4 on 13 Oct, so Bangalore is targeted nowhere.', 'Limit to the cities patients can actually reach (Delhi NCR, Bangalore), using Presence targeting. Keep other states only if the doctor travels or consults online.', 'New campaign targets Delhi, Faridabad, Ghaziabad, Gurugram and Noida only. Bangalore is closed, Lucknow not open yet. Verify Presence is selected.', 'me', '2026-10-18', '2026-10-18', 6),
((select id from public.projects where slug = 'tailbone-treatment'), 'The clinic has two websites that disagree', 'high', 'waiting_client', 'tailbonetreatment.com is the older WordPress site: it still lists a Bangalore clinic and calls itself India’s No. 1. The newer site (tailbone.onrender.com, canonical tailbone.netlify.app) lists New Delhi, online, Lucknow soon and Bengaluru closed, with a booking system, consultation ₹800 and follow-up ₹500. The old conversion tags belong to the old site.', 'Move the new site onto the clinic’s own domain, tailbonetreatment.com, so there is one site. Until then, remove Bangalore and superlative claims from the old pages. Install and test the Google tag on the new site before ads go live.', 'Still open, and it blocks launch: the ad’s final URL is tailbonetreatment.com, which still mentions Bangalore and “India’s No. 1”. Clean it or point the ad at the new site.', 'client', '2026-10-18', null, 7),
((select id from public.projects where slug = 'tailbone-treatment'), 'PMax-5 keeps being reset, so it never settles', 'high', 'superseded', 'Budget ₹230 to ₹380 (18 Sep), then ₹380 to ₹180 (29 Sep). Locations edited on 18 Sep and 25 Sep. New headlines, long headlines, search themes and the audience persona were replaced on 16 Oct.', 'Freeze both PMax campaigns for 14 days except for the conversion and geography fixes. Then judge on real enquiries only.', 'PMax-5 is paused, so the reset problem has stopped. Rule from now on: one big change per campaign every 14 days, logged.', 'me', '2026-10-18', '2026-10-18', 8),
((select id from public.projects where slug = 'tailbone-treatment'), 'Two video campaigns took 15% of spend since 1 August', 'high', 'resolved', 'Video Views Camp 1 (1 Aug to 6 Sep) cost ₹1,891 net after ₹315 was credited back. YouTube Promotion started 11 Oct at ₹72 and climbed to ₹262 a day, now your largest daily spender: ₹1,201 in 7 days for 15,577 views or clicks, about ₹0.08 each. Both buy views, not appointments, and neither appears in your Campaigns view.', 'Pause YouTube Promotion unless you can show calls from it. Do not restart view campaigns until Search and tracking work. Judge any video spend on calls and appointments only.', 'YouTube Promotion paused. Video Views Camp 1 ended 6 Sep. No view campaigns until Search and tracking prove themselves.', 'me', '2026-10-18', '2026-10-18', 9),
((select id from public.projects where slug = 'tailbone-treatment'), 'PMax-5 spend swings between zero and double budget', 'medium', 'superseded', 'Over 78 days PMax-5 spent under ₹40 on 23 days and ₹330 or more on 21 days (median day ₹225). Zero days with funds available: 22–23 Sep, 26–28 Sep (after the 25 Sep location edit), 12 Oct and 15 Oct. On 15 Oct all three campaigns went near zero together. PMax-4 also spent ₹279 on two of its three live days, double its ₹140 budget, and nothing on 15 Oct.', 'Treat the daily budget as an average: the monthly cap is 30.4 × the daily budget. Stop editing for 14 days so delivery can settle, and open the policy view on zero days.', 'PMax-5 is paused. The new campaign’s ₹200 is an average: one day can reach ₹400, a month cannot pass 30.4 × ₹200.', 'me', '2026-10-18', '2026-10-18', 10),
((select id from public.projects where slug = 'tailbone-treatment'), 'Most assets are policy-limited, and two are disapproved', 'high', 'resolved', '“Most asset groups limited by policy”. 25 of 34 assets read Approved (limited). Disapproved: the coccygodynia sitelink and one logo. PMax-5 text includes “Exercise and Back Pain cure”, “Rated Chiropractors in India”, “proven methods” and “lasting relief”, which are claim-risk wording.', 'Open Policy manager and read which policy each flag cites. Remove cure, rated, proven and lasting claims. Re-submit the two assets. Verify before applying for healthcare certification (see note below).', 'PMax assets no longer serve. The new ad has no cure, rated, proven or No. 1 claims, and three flagged keywords were removed.', 'me', '2026-10-18', '2026-10-18', 11),
((select id from public.projects where slug = 'tailbone-treatment'), 'Target CPA values fight reality', 'medium', 'superseded', 'PMax-5 target ₹17.19 locks in whatever cheap action converts. PMax-4 target ₹43 against ₹21.50 CPC would need over 50% of clicks to convert, but actual cost per conversion is ₹62.11, so bidding is throttled.', 'After the conversion fix, run Maximise conversions for about two weeks, then set Target CPA near 1.2× the cost per real enquiry.', 'New campaign uses Maximise clicks with a ₹40 cap. Target CPA comes back only after real calls are recorded.', 'me', '2026-10-18', '2026-10-18', 12),
((select id from public.projects where slug = 'tailbone-treatment'), 'No Search campaign at all', 'medium', 'resolved', 'Search impressions are 0 in the window. Condition-based searches (“tailbone pain treatment”, “coccyx pain doctor Delhi”) are the highest-intent traffic. Sitelink clicks costing ₹12 to ₹16 show what that intent costs.', 'Launch a Search campaign on phrase and exact match with negatives, call and location assets, and clinic-hours scheduling.', 'Search | Tailbone | Delhi NCR | Oct 2026 published: 15 phrase and exact keywords, Search network only, start 19 Oct.', 'me', '2026-10-18', '2026-10-18', 13),
((select id from public.projects where slug = 'tailbone-treatment'), 'Asset clutter and Average ad strength', 'medium', 'resolved', '24 sitelinks, 12 with zero impressions, many duplicated across both campaigns. Both asset groups show ad strength Average.', 'Delete zero-impression duplicates, keep 4 to 6 strong sitelinks per campaign, and add proper video and image variety.', 'New campaign starts clean with 4 sitelinks and ad strength Good. Old clutter sits in paused campaigns.', 'me', '2026-10-18', '2026-10-18', 14),
((select id from public.projects where slug = 'tailbone-treatment'), 'Scores and prompts to ignore for now', 'low', 'in_progress', 'Optimisation score 93% and 89% measures applied suggestions, not patients. “Optimise budgets +2.8%” would buy more of the same clicks. “Improve app bidding coverage” does not apply, since you run no app campaign.', 'Dismiss them. Do not apply budget recommendations until conversions are clean.', 'Auto-apply recommendations being turned off. Budget prompts stay dismissed until conversions are clean.', 'me', '2026-10-18', null, 15);
